import it.servizidigitali.presentatoreforms.bandi.frontend.constants.PresentatoreFormsPortletKeys;
import it.servizidigitali.presentatoreforms.bandi.frontend.service.PresentatoreFormFrontendService;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import javax.portlet.ResourceRequest;
import javax.portlet.ResourceResponse;
import javax.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Component(//
		immediate = true, //
		property = { //
				"javax.portlet.name=" + PresentatoreFormsPortletKeys.PRESENTATOREFORMS, //
				"mvc.command.name=/verificaRequisitoContestuale" }, //
		service = { MVCResourceCommand.class }//
)
public class VerificaRequisitoContestualeResourceCommand extends BaseMVCResourceCommand {
	private static final Log log = LogFactoryUtil.getLog(VerificaRequisitoContestualeResourceCommand.class);

	@Reference
	private PresentatoreFormFrontendService presentatoreFormFrontendService;

    @Reference
    private RequisitoDomandaBandoLocalService requisitoDomandaBandoLocalService;

    @Reference
    private ValidaDomandaBandoService validaDomandaBandoService;

	@Override
	protected void doServeResource(ResourceRequest resourceRequest, ResourceResponse resourceResponse)
			throws Exception {

		HttpServletRequest httpReq = PortalUtil.getHttpServletRequest(resourceRequest);
		HttpServletRequest httpOrigReq = PortalUtil.getOriginalServletRequest(httpReq);
        String dataForm = httpOrigReq.getParameter("dataForm");
        String jsonPathCampo = httpOrigReq.getParameter("jsonPathCampo");

		ThemeDisplay themeDisplay = (ThemeDisplay) resourceRequest.getAttribute(WebKeys.THEME_DISPLAY);
		Bando bando = presentatoreFormFrontendService.getCurrentBando(themeDisplay);

		JsonObject payload = new JsonObject();
		String status = "OK";
        List<ErroreValidazioneDTO> erroreValidazioneDTOS = new ArrayList<ErroreValidazioneDTO>();

        try {
            if(Validator.isNotNull(dataForm) && Validator.isNotNull(jsonPathCampo)) {
                List<RequisitoDomandaBando> requisitoDomandaBandoList = requisitoDomandaBandoLocalService.getRequisitoDomandaBandoByBandoIdAndTipologiaValidazioneAndCodiceRequisito(bando.getBandoId(), TipologiaValidazione.CONTESTUALE.name(), jsonPathCampo);
                if (ListUtil.isNotNull(requisitoDomandaBandoList) && ListUtil.isNotEmpty(requisitoDomandaBandoList)) {
                    erroreValidazioneDTOS = validaDomandaBandoService.validaForm(dataForm, bando.getBandoId(), themeDisplay.getLocale(), requisitoDomandaBandoList);
                    if (ListUtil.isNotNull(erroreValidazioneDTOS) && ListUtil.isNotEmpty(erroreValidazioneDTOS)) {
                        status = "KO";
                    }
                }
            }
        }catch (Exception e) {
            log.error("Errore nel controllo del requisito contestuale:: " + e);
        }

        JsonArray response = new JsonArray();
        for (ErroreValidazioneDTO erroreDto:erroreValidazioneDTOS) {
            JsonObject errore = new JsonObject();
            errore.addProperty("messaggio", erroreDto.getDescrizione());
            errore.addProperty("obbligatorio", erroreDto.isObbligatorio());
            response.add(errore);
        }
		payload.addProperty("status", status);
		payload.add("errori", response);

		String json = payload.toString();
		resourceResponse.getPortletOutputStream().write(json.getBytes());

	}

}

package it.servizidigitali.gestionebandi.common.service;

import java.util.List;
import java.util.Locale;

import it.servizidigitali.gestionebandi.common.model.ErroreValidazioneDTO;
import it.servizidigitali.gestionebandi.model.RequisitoDomandaBando;

/**
 * Servizio per la validazione delle domande di bando.
 * Verifica che i dati compilati nel form Alpaca rispettino tutti i requisiti
 * configurati per il bando (campi obbligatori, vincoli di formato, regole di business).
 *
 * @author Servizi Digitali
 * @see ErroreValidazioneDTO
 * @see RequisitoDomandaBando
 */
public interface ValidaDomandaBandoService {

	/**
	 * Valida i dati del form Alpaca rispetto ai requisiti del bando.
	 * Controlla:
	 * <ul>
	 *   <li>Campi obbligatori non compilati</li>
	 *   <li>Vincoli di formato (email, date, numeri)</li>
	 *   <li>Requisiti specifici configurati nel bando</li>
	 * </ul>
	 *
	 * @param alpacaFormData i dati JSON del form compilato
	 * @param bandoId l'identificativo del bando
	 * @param locale la lingua per i messaggi di errore
	 * @param requisitoDomandaBandoLst i requisiti specifici da verificare
	 * @return la lista degli errori di validazione riscontrati (vuota se valido)
	 */
	List<ErroreValidazioneDTO> validaForm(String alpacaFormData, long bandoId, Locale locale, List<RequisitoDomandaBando> requisitoDomandaBandoLst);

}

