267			if (optionsFields != null) {
268				JsonNode fields = optionsFields.get(0);
269	
270				if(fields!=null && fields.has(nomeCampo) && fields.get(nomeCampo)!=null){
271					JsonNode fieldsCampo = fields.get(nomeCampo);
272	                return !fieldsCampo.isObject()
273	                        || !fieldsCampo.has("numerico") || !fieldsCampo.get("numerico").asBoolean(false);
274	            }
275	
276			}
277	
278			String jsonPath = getPathTypeFromCodiceRequisito(codiceRequisito);
279			JsonNode jsonNodes = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(jsonPath);
280	
281			if (Validator.isNotNull(jsonNodes) && Validator.isNotNull(jsonNodes.get(0))) {
282				String type = jsonNodes.get(0).asText();
283				if ("text".equalsIgnoreCase(type) || "textarea".equalsIgnoreCase(type)) {
284					return true;
285				}
286			}
287	
288			return false;
