299		private ErroreValidazioneDTO validateString(String alpacaFormData, ValoreRequisitoDomanda valoreRequisito, JsonNode valoreNodo, RequisitoDomandaBando requisito, Locale locale) throws FormValidationException{
300			ErroreValidazioneDTO error = null;
301			Operazione operazione = null;
302			
303			if(requisito.getOperazioneId()>0) {
304				operazione = operazioneLocalService.fetchOperazione(requisito.getOperazioneId());
305			}
306			
307			switch (operazione.getOperazione()){
308				case FormOperators.EQ:
309					if(!(valoreRequisito.getValoreRequisitoDomanda().trim().equalsIgnoreCase(valoreNodo.asText().trim()))){
310						error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
311					}
312					break;
313	
314				case FormOperators.NE:
315					if((valoreRequisito.getValoreRequisitoDomanda().trim().equalsIgnoreCase(valoreNodo.asText().trim()))){
316						error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
317					}
318					break;
319	
320				case FormOperators.NN:
321					if (Validator.isNull(valoreNodo.asText().trim())) {
322						error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
323					}
324					break;
325	
326				case FormOperators.CONTAINS:
327					if (!valoreNodo.asText().trim().toUpperCase().contains(valoreRequisito.getValoreRequisitoDomanda().trim().toUpperCase())) {
328						error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisito, valoreNodo.asText().trim(), String.class);
329					}
330					break;
331	
332				default:
333					throw new RuntimeException("operatore non supportato RequisitoDomandaBando id :: " + requisito.getRequisitoDomandaBandoId());
334			}
335			return error;
336		}
