338		private String getPathTypeFromCodiceRequisito(String codiceRequisito) {
339	        StringBuilder outJsonPat = new StringBuilder();
340	        outJsonPat.append(ALPACA_ALPACA_FIELD + ALPACA_OPTION_FIELD + ALPACA_FIELDS_FIELD);
341	        Pattern pattern = Pattern.compile(ALPACA_REGEX_ESTRAZIONE_NODI);
342	        Matcher matcher = pattern.matcher(codiceRequisito);
343	
344	        List<String> nodi = new ArrayList<>();
345	        while (matcher.find()) {
346	            nodi.add(matcher.group(1));
347	        }
348	        
349	        if (!nodi.isEmpty()) {
350	        	for (int i = 0; i < nodi.size(); i++) {  
351	        	    String nodo = nodi.get(i);    	  
352	        	    outJsonPat.append(ALPACA_FIELD_OPEN_PATTERN).append(nodo).append(ALPACA_FIELD_CLOSING_PATTERN);       	    
353	        	    if (i < nodi.size() - 1) { 
354	        	        outJsonPat.append(ALPACA_FIELDS_FIELD);
355	        	    } else {
356	        	    	outJsonPat.append(ALPACA_TYPE_FIELD);
357	        	    }
358	        	}
359	        }      
360	       return outJsonPat.toString();
361	    }
