	private ErroreValidazioneDTO validateFidelINCondition(String alpacaFormData,
			List<ValoreRequisitoDomanda> valoreRequisitoLst, JsonNode valoreNodo, RequisitoDomandaBando requisito,
			Locale locale, Boolean campoTestuale) {

		ErroreValidazioneDTO error = null;

		if (campoTestuale) {
			List<String> listaValori = new ArrayList<String>();
			for (ValoreRequisitoDomanda valoreRequisito : valoreRequisitoLst) {
				listaValori.add(valoreRequisito.getValoreRequisitoDomanda().trim());
			}
			if (!listaValori.contains(valoreNodo.asText().trim())) {
				error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisitoLst.get(0),valoreNodo.asText().trim(), String.class);
			}
		} else {
			List<BigDecimal> listaValori = new ArrayList<BigDecimal>();
			for (ValoreRequisitoDomanda valoreRequisito : valoreRequisitoLst) {
				if (isDecimalNumber(valoreRequisito.getValoreRequisitoDomanda())){
					listaValori.add( new BigDecimal(normalizeDecimalNumber(valoreRequisito.getValoreRequisitoDomanda())));
				}
			}
			BigDecimal formNumber = null;
			if (isDecimalNumber(valoreNodo.asText())){
				formNumber = new BigDecimal(normalizeDecimalNumber(valoreNodo.asText()));
				if (!listaValori.contains(formNumber)) {
					error = this.buildErroreValidazioneDTO(alpacaFormData, locale, requisito, valoreRequisitoLst.get(0),valoreNodo.asText().trim(), String.class);
				}
			}
		}
		return error;
	}

	private boolean isCampoTestuale(String codiceRequisito, Configuration jsonPathConfiguration, String alpacaFormData) {
		if (!Validator.isNotNull(codiceRequisito)) {
			return false;
		}

		String pathCampo = codiceRequisito.substring(codiceRequisito.indexOf("["), codiceRequisito.indexOf("]") + 1);
		String nomeCampo = codiceRequisito.substring(codiceRequisito.lastIndexOf("['") + 2, codiceRequisito.lastIndexOf("']"));

		JsonNode optionsFields = JsonPath.using(jsonPathConfiguration)
				.parse(alpacaFormData)
				.read(ALPACA_ALPACA_FIELD + ALPACA_OPTION_FIELD + ALPACA_FIELDS_FIELD + pathCampo + ALPACA_FIELDS_FIELD);

		if (optionsFields != null) {
			JsonNode fields = optionsFields.get(0);

			if(fields!=null && fields.has(nomeCampo) && fields.get(nomeCampo)!=null){
				JsonNode fieldsCampo = fields.get(nomeCampo);
                return !fieldsCampo.isObject()
                        || !fieldsCampo.has("numerico") || !fieldsCampo.get("numerico").asBoolean(false);
            }

		}

		String jsonPath = getPathTypeFromCodiceRequisito(codiceRequisito);
		JsonNode jsonNodes = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(jsonPath);

		if (Validator.isNotNull(jsonNodes) && Validator.isNotNull(jsonNodes.get(0))) {
			String type = jsonNodes.get(0).asText();
			if ("text".equalsIgnoreCase(type) || "textarea".equalsIgnoreCase(type)) {
				return true;
			}
		}

		return false;
	}

