	private boolean isDate(String input){
		try{
			LocalDate date = LocalDate.parse(input, DateTimeFormatter.ofPattern("dd/MM/yyyy"));
			return true;
		}catch(DateTimeParseException e){
			log.debug("impossibile parsare il valore in input. probabilmente non si tratta di una stringa oppure ha un formato errato.");
		}
		return false;
	}

	/**
	 * Verifica se la stringa rappresenta un numero valido (intero o decimale).
	 * Supporta numeri come: 123, -123, 123.78, -123.78, 123,78, -123,78
	 *
	 * @param input la stringa da verificare
	 * @return true se la stringa rappresenta un numero valido, false altrimenti
	 */
	private boolean isDecimalNumber(String input) {
		if (Validator.isBlank(input)) {
			return false;
		}
		try {
			new BigDecimal(normalizeDecimalNumber(input));
			return true;
		} catch (NumberFormatException e) {
			return false;
		}
	}

	/**
	 * Normalizza una stringa numerica sostituendo la virgola con il punto come separatore decimale.
	 *
	 * @param input la stringa da normalizzare
	 * @return la stringa normalizzata con il punto come separatore decimale
	 */
	private String normalizeDecimalNumber(String input) {
		if (Validator.isBlank(input)) {
			return input;
		}
		return input.trim().replace(",", ".");
	}

	private String getValueFromJsonPath(String alpacaFormData, String jsonPath) {
		String value = null;

		Set<Option> jsonPathOptions = new HashSet<Option>();
		jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
		jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

		Configuration jsonPathConfiguration = Configuration.builder()
				.jsonProvider(new JacksonJsonNodeJsonProvider())
				.mappingProvider(new JacksonMappingProvider())
				.options(jsonPathOptions)
				.build();

		String fieldName = getFieldNameFromJsonPathPattern(jsonPath);
		List<String> pathFieldFound = JsonPath.using(Configuration.builder().options(Option.AS_PATH_LIST).build()).parse(alpacaFormData).read("$.." + fieldName);
		List<String> nomiPath = new ArrayList<String>();
		nomiPath.add(ALPACA_ALPACA_FIELD);
		nomiPath.add(ALPACA_DATA_FIELD);

		List<String> pathFound = filterPathByFieldList(pathFieldFound, nomiPath);

		JsonNode fieldValues = null; 
		if (Validator.isNotNull(pathFound) && !pathFound.isEmpty()) {
			if (pathFound.size() > 1) {
				//TODO ottimizzare gestione
				String field = jsonPath.substring(jsonPath.indexOf(".") + 1);
				String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD+ field;

				fieldValues = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(jsonPathInterno);

			} else {
                fieldValues = JsonPath.using(jsonPathConfiguration).parse(alpacaFormData).read(pathFound.get(0));
			}
		}

		if(fieldValues!=null && !fieldValues.isEmpty()) {
			value = fieldValues.get(0).asText();
		}


		return value;
	}

	private int validateNumberOperatorPercentuale(String alpacaFormData, ValoreRequisitoDomanda valoreRequisito, BigDecimal formNumber) {
		int compareToEval = 0;
		BigDecimal valoreNumber = new BigDecimal(normalizeDecimalNumber(valoreRequisito.getValoreRequisitoDomanda()));


		Operazione operazione = operazioneLocalService.fetchOperazione(valoreRequisito.getOperazioneId());

		if(Validator.isNotNull(operazione) && operazione.getOperazione().equalsIgnoreCase(FormOperators.PE)) {
			String valoreRiferimentoForm = getValueFromJsonPath(alpacaFormData, valoreRequisito.getValoreRiferimento());

			if(Validator.isNotNull(valoreRiferimentoForm)) {
				BigDecimal valoreRiferimentoFormNumber = new BigDecimal(normalizeDecimalNumber(valoreRiferimentoForm));
				BigDecimal valoreCalcolato = valoreNumber.multiply(valoreRiferimentoFormNumber).divide(new BigDecimal(100));

				compareToEval = formNumber.compareTo(valoreCalcolato);
			}

		}


		return compareToEval;
	}

