                String valoreRiferimento = ParamUtil.getString(actionRequest, GestioneBandiFrontendPortletKeys.VALORE_RIFERIMENTO + i);
                boolean requisitoPreValidazione = ParamUtil.getBoolean(actionRequest, GestioneBandiFrontendPortletKeys.REQUISITO_TIPOLOGIA_VALIDAZIONE_PRE + i);
                boolean requisitoPostValidazione = ParamUtil.getBoolean(actionRequest, GestioneBandiFrontendPortletKeys.REQUISITO_TIPOLOGIA_VALIDAZIONE_POST + i);
                boolean requisitoContestuale = ParamUtil.getBoolean(actionRequest, GestioneBandiFrontendPortletKeys.REQUISITO_TIPOLOGIA_VALIDAZIONE_CONTESTUALE + i);

                Integer indexValori = 0;

                if (mappaValoriRequisito != null) {
                    indexValori = (Integer) mappaValoriRequisito.get(String.valueOf(i));
                }

                List<String> listaValori = new ArrayList<>();

                if (Validator.isNotNull(indexValori)) {
                    for (int j = 1; j <= indexValori; j++) {
                        String valoreRequisito = ParamUtil.getString(actionRequest, GestioneBandiFrontendPortletKeys.VALORE_REQUISITO + i + "-" +j);
                        listaValori.add(valoreRequisito);
                    }
                }

                if (Validator.isNull(requisitoDomandaBandoId) || requisitoDomandaBandoId == 0) {
                    requisitoDomandaBando = requisitoDomandaBandoLocalService.createRequisitoDomandaBando(CounterLocalServiceUtil.increment());
                } else {
                    requisitoDomandaBando = requisitoDomandaBandoLocalService.getRequisitoDomandaBando(requisitoDomandaBandoId);
                }

                if ("".equals(codiceRequisito) || operazioneId == 0) {
                    continue;
                }

                requisitoDomandaBando.setBandoId(bando.getBandoId());
                requisitoDomandaBando.setOperazioneId(operazioneId);
                requisitoDomandaBando.setCodiceRequisito(codiceRequisito);
                requisitoDomandaBando.setGroupId(siteGroupId);
                requisitoDomandaBando.setCompanyId(companyId);
                requisitoDomandaBando.setUserId(userId);
                requisitoDomandaBando.setUserName(userFullName);
                requisitoDomandaBando.setObbligatorio(obbligatorio);
                requisitoDomandaBando.setMostraValoreCorretto(mostraValoreCorretto);

                if(requisitoPreValidazione){
                    requisitoDomandaBando.setTipologiaValidazione(TipologiaValidazione.PREVALIDAZIONE.name());
                }

                if(requisitoPostValidazione){
                    requisitoDomandaBando.setTipologiaValidazione(TipologiaValidazione.POSTVALIDAZIONE.name());
                }

                if(requisitoContestuale){
                    requisitoDomandaBando.setTipologiaValidazione(TipologiaValidazione.CONTESTUALE.name());
                }

                for (String valoreRequisito : listaValori) {

                    if (Validator.isNotNull(valoreRifOperazioneId) && valoreRifOperazioneId == 0) {
                        valoreRifOperazioneId = null;
                        valoreRiferimento = null;
                    }

                    if (Validator.isNotNull(valoreRifOperazioneId) && Validator.isBlank(valoreRiferimento)) {
                        auditService.saveErrorLog(actionRequest, "valoreRiferimento obbligatorio se operazioneId risulta valorizzata");
                        // valoreRiferimento obbligatorio se valoreRifOperazioneId risulta valorizzata
                        SessionErrors.add(actionRequest, GestioneBandiFrontendPortletKeys.SESSION_ERROR_CAMPI_OBBLIGATORI);
                        _log.error("GestioneBando :: salvaCrea :: Compilare tutti i campi obbligatori! :: valoreRiferimento obbligatorio se operazioneId risulta valorizzata");
//                    actionResponse.getRenderParameters()
//                                  .setValue("jspPage", GestioneBandiFrontendPortletKeys.JSP_AGGIUNGI_MODIFICA_BANDO);
                        renderParameters.setValue("mvcRenderCommandName", GestioneBandiFrontendPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND);
                        return;
                    }

                    if (!(valoreRequisito == null || "".equals(valoreRequisito))) {
                        valoreRequisitoDomanda = valoreRequisitoDomandaLocalService.createValoreRequisitoDomanda(CounterLocalServiceUtil.increment());
                        valoreRequisitoDomanda.setGroupId(siteGroupId);
                        valoreRequisitoDomanda.setCompanyId(companyId);
                        valoreRequisitoDomanda.setUserId(userId);
                        valoreRequisitoDomanda.setUserName(userFullName);
                        valoreRequisitoDomanda.setValoreRequisitoDomanda(valoreRequisito);
                        valoreRequisitoDomanda.setRequisitoDomandaBandoId(requisitoDomandaBando.getRequisitoDomandaBandoId());

                        if (valoreRifOperazioneId != null && valoreRifOperazioneId > 0) {

                            valoreRequisitoDomanda.setOperazioneId(valoreRifOperazioneId);
                            valoreRequisitoDomanda.setValoreRiferimento(valoreRiferimento);
                        }

                        listaValoriRequisiti.add(valoreRequisitoDomanda);
                    }

                }
                // se non ho valori nella lista dei valori passo al prossimo requisito domanda
                // senza salvarlo
                if (listaValoriRequisiti.isEmpty()) {
                    continue;
                }
                // qui ci saranno alla fine del ciclo tutti gli id da tenere
                listaIdRequisiti.add(requisitoDomandaBando.getRequisitoDomandaBandoId());
                listaRequisiti.add(requisitoDomandaBando);
            }
        }
        // --------------------- RICERCA BANDI --------------------------------
        List<Long>              listaIdValoriDatiBando  = new ArrayList<>();
        List<ValoreDatoBando>   listaValoriDatiBando    = new ArrayList<>();

        // ---------------------CODICE ATECO--------------------------------
        String rowIndexesCodiciAteco = ParamUtil.getString(actionRequest, "rowIndexesCodiciAteco");

        if(Validator.isNotNull(rowIndexesCodiciAteco)&&rowIndexesCodiciAteco!="") {
            this.prepareValoriDatoBando(
                    actionRequest,
                    rowIndexesCodiciAteco,
                    CodiceDatoBandoEnum.CODICI_ATECO,
                    GestioneBandiFrontendPortletKeys.VALORE_DATO_BANDO_CODICE_ATECO,
                    GestioneBandiFrontendPortletKeys.ID_VALORE_DATO_BANDO_CODICE_ATECO,
                    listaIdValoriDatiBando,
                    listaValoriDatiBando,
                    bando.getBandoId(),
                    userFullName,
                    userId,
                    siteGroupId,
                    companyId
            );
        }
        // ---------------------TIPOLOGIA BENEFICIARIO--------------------------------
        String valoreDatoBandoTipologiaBeneficiario   = ParamUtil.getString(actionRequest, GestioneBandiFrontendPortletKeys.VALORE_DATO_BANDO_TIPOLOGIA_BENEFICIARIO);
        long idValoreDatoBandoTipologiaBeneficiario   = ParamUtil.getLong(actionRequest, GestioneBandiFrontendPortletKeys.ID_VALORE_DATO_BANDO_TIPOLOGIA_BENEFICIARIO);

        if(valoreDatoBandoTipologiaBeneficiario !=null && !"".equals(valoreDatoBandoTipologiaBeneficiario)){
            this.prepareValoriDatoBandoSelectRicercaBando(
                    CodiceDatoBandoEnum.TIPOLOGIA_BENEFICIARI,
                    valoreDatoBandoTipologiaBeneficiario,
                    idValoreDatoBandoTipologiaBeneficiario,
                    listaIdValoriDatiBando,
                    listaValoriDatiBando,
                    bando.getBandoId(),
                    userFullName,
                    userId,
                    siteGroupId,
                    companyId
            );
        }

        // ---------------------DIMENSIONE AZIENDALE--------------------------------
        DatoBando datoBandoTipologiaBeneficiario = datoBandoLocalService.findByCodice(CodiceDatoBandoEnum.TIPOLOGIA_BENEFICIARI.name());
        ValoreDatoBando valoreDatoBandoBeneficiario = listaValoriDatiBando.stream()
                .filter(valoreDatoBando -> valoreDatoBando.getDatoBandoId() == datoBandoTipologiaBeneficiario.getDatoBandoId())
                .findFirst()
                .orElse(null);

        String valoreDatoBandoDimensioneAziendale   = ParamUtil.getString(actionRequest, GestioneBandiFrontendPortletKeys.VALORE_DATO_BANDO_DIMENSIONE_AZIENDALE);
        long idValoreDatoBandoDimensioneAziendale   = ParamUtil.getLong(actionRequest, GestioneBandiFrontendPortletKeys.ID_VALORE_DATO_BANDO_DIMENSIONE_AZIENDALE);

        // solo se e' stato selezionato "IMPRESA", allora ammetto la dimensione
        if(valoreDatoBandoBeneficiario != null && valoreDatoBandoBeneficiario.getValore().equalsIgnoreCase(TipologiaBeneficiariEnum.IMPRESE.name()) && valoreDatoBandoDimensioneAziendale != null && !"".equals(valoreDatoBandoDimensioneAziendale)){
            this.prepareValoriDatoBandoSelectRicercaBando(
                    CodiceDatoBandoEnum.DIMENSIONE_AZIENDALE,
                    valoreDatoBandoDimensioneAziendale,
                    idValoreDatoBandoDimensioneAziendale,
                    listaIdValoriDatiBando,
                    listaValoriDatiBando,
                    bando.getBandoId(),
                    userFullName,
                    userId,
                    siteGroupId,
                    companyId
            );
        }

        // ---------------------CODICE ATECO RILEVANZA--------------------------------
        String valoreDatoBandoCodiceAtecoRilevanza   = ParamUtil.getString(actionRequest, GestioneBandiFrontendPortletKeys.VALORE_DATO_BANDO_CODICE_ATECO_RILEVANZA);
        long idValoreDatoBandoCodiceAtecoRilevanza   = ParamUtil.getLong(actionRequest, GestioneBandiFrontendPortletKeys.ID_VALORE_DATO_BANDO_CODICE_ATECO_RILEVANZA);

        if(valoreDatoBandoCodiceAtecoRilevanza != null && !"".equals(valoreDatoBandoCodiceAtecoRilevanza)){
            this.prepareValoriDatoBandoSelectRicercaBando(
                    CodiceDatoBandoEnum.CODICE_ATECO_RILEVANZA,
                    valoreDatoBandoCodiceAtecoRilevanza,
                    idValoreDatoBandoCodiceAtecoRilevanza,
                    listaIdValoriDatiBando,
                    listaValoriDatiBando,
                    bando.getBandoId(),
                    userFullName,
                    userId,
                    siteGroupId,
                    companyId
            );
        }

        // ---------------------DISABILITA CONTROLLO IMPORTO AMMISSIBILE--------------------------------
        this.prepareValoriDatoBando(
                actionRequest,
                "1",
                CodiceDatoBandoEnum.DISABILITA_CONTROLLO_IMPORTO_AMMISSIBILE,
                GestioneBandiFrontendPortletKeys.DISABILITA_CONTROLLO_IMPORTO_AMMISSIBILE,
