public class VerificaDomandaBandoActionCommand extends BaseMVCActionCommand {

	public static final Log _log = LogFactoryUtil.getLog(VerificaDomandaBandoActionCommand.class);

	@Reference
	private PresentatoreFormFrontendService presentatoreFormFrontendService;

	@Reference
	private DefinizioneAllegatoLocalService definizioneAllegatoLocalService;

	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;

	@Reference
	private PDFServiceFactory pdfServiceFactory;

	@Reference
	private CommunicationService communicationService;

	@Reference
	private AllegatoDomandaBandoService allegatoDomandaBandoService;

	@Reference
	private ValidaDomandaBandoService validaDomandaBandoService;

	@Reference
	private AuditService auditService;

	@Reference
	private RequisitoDomandaBandoLocalService requisitoDomandaBandoLocalService;

	@Reference
	private AllegatoDomandaBandoLocalService allegatoDomandaBandoLocalService;

	private ConfigurationProvider configurationProvider;

	private volatile BandiInserimentoElencoConfiguration bandiInserimentoElencoConfiguration;

	@Reference
	protected void setConfigurationProvider(ConfigurationProvider configurationProvider) {
		this.configurationProvider = configurationProvider;
	}

	@Override
	protected void doProcessAction(ActionRequest actionRequest, ActionResponse actionResponse) throws Exception {
		ThemeDisplay themeDisplay = (ThemeDisplay) actionRequest.getAttribute(WebKeys.THEME_DISPLAY);

		ResourceBundleLoader resourceBundleLoader = ResourceBundleLoaderUtil.getResourceBundleLoaderByBundleSymbolicName(PresentatoreFormsPortletKeys.BUNDLE_SYMBOLIC_NAME);
		Long domandaBandoId = (Long) actionRequest.getAttribute("domandaBandoId");

		User user = themeDisplay.getUser();
		Bando bando = null;
		Form form = null;
		List<ErroreValidazioneDTO> erroreValidazioneDTOS = new ArrayList<ErroreValidazioneDTO>();
		UserPreferences userPreferences = new UserPreferences();
		userPreferences.setCodiceFiscaleRichiedente(user.getScreenName());
		userPreferences.setCompanyId(themeDisplay.getCompanyId());
		IstanzaDomandaBando istanzaDomandaBando = null;

		Boolean isDomandaInviabile = true;
		try {
			bando = presentatoreFormFrontendService.getCurrentBando(themeDisplay);
			form = presentatoreFormFrontendService.getFormBando(bando.getBandoId());
			if (Validator.isNull(domandaBandoId)) {
				domandaBandoId = ParamUtil.getLong(actionRequest, "domandaBandoId", 0);
			}
			if (Validator.isNotNull(bando) && bando.getBandoId() > 0 && Validator.isNotNull(domandaBandoId)) {
				DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

				if (Validator.isNotNull(form)) {
					IstanzaDomandaBando istanzaForm = presentatoreFormFrontendService.getIstanzaDomandaBando(domandaBando.getDomandaBandoId(), form.getFormId());
					actionRequest.setAttribute(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, domandaBando.getDomandaBandoId());
//					! FILIERIM
					try {
						bando = presentatoreFormFrontendService.getCurrentBando(themeDisplay);
						form = presentatoreFormFrontendService.getFormBando(bando.getBandoId());
						if (Validator.isNotNull(form)) {
							List<RequisitoDomandaBando> requisitoDomandaBandoLst = requisitoDomandaBandoLocalService.getRequisitoDomandaBandoByBandoIdAndTipologiaValidazione(bando.getBandoId(), TipologiaValidazione.POSTVALIDAZIONE.name());
							erroreValidazioneDTOS = validaDomandaBandoService.validaForm(istanzaForm.getJson(), bando.getBandoId(), themeDisplay.getLocale(), requisitoDomandaBandoLst);
							//Controllo cap per bandi

							try {
								bandiInserimentoElencoConfiguration = configurationProvider.getGroupConfiguration(BandiInserimentoElencoConfiguration.class, themeDisplay.getScopeGroupId());
							} catch (ConfigurationException e) {
								_log.error("Errore nel recupero della configurazione inserimento elenco bandi :: ", e);
							}
							String codiciBandiInsegneStoriche = bandiInserimentoElencoConfiguration.codiciBandiInsegneStoriche();
							if (Validator.isNotNull(codiciBandiInsegneStoriche)) {
								List<String> listaCodiBandiInsegneStoriche = Arrays.asList(codiciBandiInsegneStoriche.split(","));
								if (listaCodiBandiInsegneStoriche.contains(bando.getCodice())){
									presentatoreFormFrontendService.addExtraValidationErrors(erroreValidazioneDTOS, themeDisplay.getScopeGroupId(), themeDisplay.getPortalURL(), istanzaForm.getFormId(), istanzaForm.getJson(), bando.getBandoId(), themeDisplay.getLocale());
								}
							}

							actionRequest.setAttribute(PresentatoreFormsPortletKeys.LISTA_ERRORI_VALIDAZIONE, erroreValidazioneDTOS);
							actionRequest.setAttribute(PresentatoreFormsPortletKeys.INVIO_ISTANZA, true);
							List<DefinizioneAllegatoDTO> definizioneAllegati = AllegatoUtil.retrieveAllegati(istanzaForm, form);
							istanzaDomandaBando = presentatoreFormFrontendService.getIstanzaDomandaBando(domandaBando.getDomandaBandoId(), form.getFormId());

							List<AllegatoDomandaBando> allegatoDomandaBandoList = allegatoDomandaBandoLocalService.getListaAllegatiByIstanzaDomandaBandoId(istanzaForm.getIstanzaDomandaBandoId());
							List<Long> allegatoDomandaBandoIds = allegatoDomandaBandoLocalService.getAllegatiByIstanzaDomandaBandoIdAndPrincipale(istanzaDomandaBando.getIstanzaDomandaBandoId(),false);

							Set<Long> allegatiVariatiIds = presentatoreFormFrontendService.recuperaAllegatiVariatiIds(definizioneAllegati, allegatoDomandaBandoIds);

							boolean ricaricamentoAllegati = Validator.isNotNull(allegatiVariatiIds) && !allegatiVariatiIds.isEmpty();

							List<AllegatoDomandaBando> allegatiVariati = new ArrayList<>();
							if (ricaricamentoAllegati) {
								for (Long idVariato: allegatiVariatiIds) {
									Optional<AllegatoDomandaBando> allegatoDomandaBando = allegatoDomandaBandoList.stream().filter(adb -> adb.getDefinizioneAllegatoId() == idVariato).findFirst();
									allegatoDomandaBando.ifPresent(allegatiVariati::add);
								}
							}
							actionRequest.setAttribute(PresentatoreFormsPortletKeys.ALLEGATI_VARIATI, allegatiVariati);
							actionRequest.setAttribute(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, domandaBandoId);

							List<DefinizioneStepAlpaca> alpacaSteps = presentatoreFormFrontendService.retrieveAlpacaSteps(form.getJson());
							int numeroStepAlpaca = alpacaSteps.size();
							actionRequest.setAttribute(PresentatoreFormsPortletKeys.NUMERO_STEP_ALPACA, numeroStepAlpaca);

							actionResponse.getRenderParameters().setValue("mvcPath", PresentatoreFormsPortletKeys.JSP_VERIFICA_DOMANDA_BANDO);
						}
					} catch (PortalException e) {
						isDomandaInviabile = false;
						throw new RuntimeException(e);
					}
				}
			}
		}catch (Exception e) {
			auditService.saveErrorLog(actionRequest, e.getMessage());
			_log.error("VerificaDomandaBandoActionCommand :: Errore durante il salvataggio della richiesta!", e);
			actionRequest.setAttribute(PresentatoreFormsPortletKeys.LISTA_ERRORI,
					resourceBundleLoader.loadResourceBundle(themeDisplay.getLocale()).getString("errore-durante-il-salvataggio-della-richiesta") + ": " + e.getMessage() + " : "
							+ resourceBundleLoader.loadResourceBundle(themeDisplay.getLocale()).getString("errore-contattare-amministratore-sistema"));

