	@Override
	public String render(RenderRequest renderRequest, RenderResponse renderResponse) throws PortletException {

		ThemeDisplay themeDisplay = (ThemeDisplay) renderRequest.getAttribute(WebKeys.THEME_DISPLAY);

		try {
			Bando bando = presentatoreFormFrontendService.getCurrentBando(themeDisplay);
			if (Validator.isNull(bando)) {
				SessionErrors.add(renderRequest, PresentatoreFormsPortletKeys.IMPOSSIBILE_RECUPERARE_PROCEDURA);
				return PresentatoreFormsPortletKeys.JSP_ERROR;
			}

			String screenName = themeDisplay.getUser().getScreenName();
			boolean isEnteVerificato = ParamUtil.getBoolean(renderRequest, "isEnteVerificato", false);
			try {

				if (bando.isObbligoAccreditamentoEnte() && !isEnteVerificato) {
					String errore = ParamUtil.getString(renderRequest, "errore");
					renderRequest.setAttribute("errore", errore);

					renderRequest.setAttribute("listaPIva", presentatoreFormFrontendService.getPartiteIvaUtente(screenName));
					return PresentatoreFormsPortletKeys.JSP_STEP_INTERMEDIO_DATI_ENTE;
				}

				if (bando.isAbilitaAnagraficaUnica() && !isEnteVerificato) {
					String errore = ParamUtil.getString(renderRequest, "errore");
					renderRequest.setAttribute("errore", errore);

					return PresentatoreFormsPortletKeys.JSP_STEP_INTERMEDIO_ANAGRAFICA_UNICA;
				}

				Form form = presentatoreFormFrontendService.getFormBando(bando.getBandoId());
				String partitaIvaCodiceFiscale = ParamUtil.getString(renderRequest, "partitaIvaCodiceFiscale");

				FormData formData = AlpacaUtil.loadFormData(form, null, true, themeDisplay.getPortalURL());
				AlpacaJsonStructure alpacaStructure = formData.getAlpaca();

				UserPreferences userPreferences = new UserPreferences();
				userPreferences.setCodiceFiscaleRichiedente(screenName);
				userPreferences.setCompanyId(themeDisplay.getCompanyId());

				Gson gson = new Gson();
				JsonObject data = gson.fromJson(gson.toJson(alpacaStructure.getData()), JsonObject.class);

				AlpacaJsonOptionsStructure optionStr = gson.fromJson(gson.toJson(alpacaStructure.getOptions()), AlpacaJsonOptionsStructure.class);
				JsonObject dataEnrich = presentatoreFormFrontendService.enrichFormBandi(themeDisplay.getUser(), data, optionStr, userPreferences, partitaIvaCodiceFiscale, bando);
				alpacaStructure.setData(dataEnrich);

				// Sostituzione valore di data
				String dataString = gson.toJson(alpacaStructure.getData());
				JsonObject jsonData = gson.fromJson(dataString, JsonObject.class);
				alpacaStructure.setData(gson.toJsonTree(jsonData).getAsJsonObject());

				String enrichedJson = gson.toJson(alpacaStructure);
				JsonObject jsonEnriched = gson.fromJson(enrichedJson, JsonObject.class);
				JsonObject jsonObject = new JsonObject();
				jsonObject.add("alpaca", jsonEnriched);
				enrichedJson = gson.toJson(jsonObject);
				//validazione preliminare
				List<ErroreValidazioneDTO> erroreValidazioneDTOS = validaDatiPreliminari(bando, enrichedJson, themeDisplay.getLocale(), partitaIvaCodiceFiscale,themeDisplay.getUser());

				renderRequest.setAttribute(PresentatoreFormsPortletKeys.PARTITA_IVA_CODICE_FISCALE, partitaIvaCodiceFiscale);
				if (Validator.isNotNull(erroreValidazioneDTOS) && !erroreValidazioneDTOS.isEmpty()) {
					renderRequest.setAttribute(PresentatoreFormsPortletKeys.LISTA_ERRORI_VALIDAZIONE, erroreValidazioneDTOS);
					return PresentatoreFormsPortletKeys.JSP_VERIFICA_PRELIMINARE_DOMANDA_BANDO;
				}

				renderRequest.setAttribute(PresentatoreFormsPortletKeys.ALPACA_STRUCTURE, alpacaStructure);
				renderRequest.setAttribute(PresentatoreFormsPortletKeys.API_ALPACA_PATH, themeDisplay.getPortalURL() + PresentatoreFormsPortletKeys.SERVIZI_DIGITALI_REST_CUSTOM_API_ALPACA_PATH);
				renderRequest.setAttribute(PresentatoreFormsPortletKeys.API_SD_PATH, themeDisplay.getPortalURL() + PresentatoreFormsPortletKeys.SERVIZI_DIGITALI_REST_API_PATH);
				renderRequest.setAttribute(PresentatoreFormsPortletKeys.OBBLIGO_ACCREDITAMENTO_ENTE, bando.isObbligoAccreditamentoEnte());
				renderRequest.setAttribute(PresentatoreFormsPortletKeys.ERRORE_BOZZA_DETTAGLIO_KEY,
						presentatoreFormFrontendService.getErroreBozzaDettaglioKey(bando.getCodice(), themeDisplay.getLocale()));

				return PresentatoreFormsPortletKeys.JSP_COMPILA_FORM;
			}
			catch(AnagraficaUnicaException e) {

				String errore = ResourceBundleLoaderUtil.getResourceBundleLoaderByBundleSymbolicName(
						PresentatoreFormsPortletKeys.BUNDLE_SYMBOLIC_NAME)
						.loadResourceBundle(Locale.ITALIAN)
						.getString("errore-anagrafica-unica");

				renderRequest.setAttribute("errore", errore);

				return PresentatoreFormsPortletKeys.JSP_STEP_INTERMEDIO_ANAGRAFICA_UNICA; 
			}
			catch (Exception e) {
				log.error(e.getMessage(), e);
				SessionErrors.add(renderRequest, PresentatoreFormsPortletKeys.GENERIC_ERROR_MESSAGE_KEY, e.getMessage());
				return PresentatoreFormsPortletKeys.JSP_ERROR;
			}
		}
		catch (PortalException e) {
			log.error("render :: " + e.getMessage(), e);
			SessionErrors.add(renderRequest, PresentatoreFormsPortletKeys.GENERIC_ERROR_MESSAGE_KEY, e.getMessage());
			return PresentatoreFormsPortletKeys.JSP_ERROR;
		}
	}

